func isDigit(r rune) bool { return r >= '0' && r <= '9' }
func isBin(r rune) bool   { return r == '0' || r == '1' }
func isHex(r rune) bool   { return isDigit(r) || r >= 'a' && r <= 'f' || r >= 'A' && r <= 'F' }
func isIdentPart(r rune) bool {
