	var total uint64
	for {
		u := l.pos
		for isAlpha(l.peek()) {
			l.adv()
		}
		mult, ok := durUnits[l.src[u:l.pos]]
		if !ok {
			return Token{}, &Error{line, col, "bad duration unit"}
		}
		n, err := strconv.ParseUint(digits, 10, 64)
		if err != nil {
			return Token{}, &Error{line, col, "duration too large"}
