}

// Token is one lexical element.
type Token struct {
	Kind      Kind
	Text      string
	Num       uint64
	Str       string
	Offset    int
	Line, Col int
}

// Error is a lexical error with its position.
type Error struct {
	Line, Col int
	Msg       string
}

func (e *Error) Error() string { return fmt.Sprintf("%d:%d: %s", e.Line, e.Col, e.Msg) }

type lexer struct {
	src       string
	pos       int
	line, col int
