func (l *lexer) skip() *Error {
	for !l.eof() {
		c := l.peek()
		switch {
		case c == ' ' || c == '\t' || c == '\r' || c == '\n':
			l.adv()
		case c == '#':
			for !l.eof() && l.peek() != '\n' {
