func (l *lexer) scanDigits(valid func(rune) bool) *Error {
	got := false
	for {
		c := l.peek()
		switch {
		case valid(c):
			l.adv()
			got = true
		case c == '_':
			if !got || !valid(l.peekAt(1)) {
				return l.errHere("bad digit separator")
			}
			l.adv()
		default:
			return nil
		}
	}
